import pytest


def shout(xs: list[str]) -> None:
    """Print each string in xs upper-cased, one per line."""
    for s in xs:
        print(s.upper())


def test_shout_basic(capsys: pytest.CaptureFixture[str]) -> None:
    shout(["hello", "world"])
    assert capsys.readouterr().out == "HELLO\nWORLD\n"


def test_shout_empty(capsys: pytest.CaptureFixture[str]) -> None:
    shout([])
    assert capsys.readouterr().out == ""


def test_shout_mixed_and_empty_string(capsys: pytest.CaptureFixture[str]) -> None:
    shout(["MiXed", "", "abc 123"])
    assert capsys.readouterr().out == "MIXED\n\nABC 123\n"


def test_shout_returns_none(capsys: pytest.CaptureFixture[str]) -> None:
    assert shout(["a"]) is None  # type: ignore[func-returns-value]
    capsys.readouterr()


def test_shout_does_not_mutate_input(capsys: pytest.CaptureFixture[str]) -> None:
    xs = ["a", "b"]
    shout(xs)
    assert xs == ["a", "b"]
    capsys.readouterr()


def test_shout_unicode(capsys: pytest.CaptureFixture[str]) -> None:
    shout(["straße", "é"])
    assert capsys.readouterr().out == "STRASSE\nÉ\n"

